package com.tencent.weknora.model.client;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.function.Consumer;

/** Go Chat Completions request semantics and SSE parsing; no SDK silently selects another protocol. */
public final class OpenAIChat implements ChatModel {
    private static final ObjectMapper JSON=SafeModelHttp.JSON;private static final List<String>LADDER=List.of("minimal","low","medium","high","xhigh","max");
    private final SafeModelHttp http;private final ModelEndpoint endpoint;private final Duration chatTimeout,streamTimeout;
    public OpenAIChat(SafeModelHttp http,ModelEndpoint endpoint,Duration chatTimeout,Duration streamTimeout){this.http=http;this.endpoint=endpoint;this.chatTimeout=chatTimeout;this.streamTimeout=streamTimeout;}
    @Override public String modelId(){return endpoint.id;}@Override public String modelName(){return endpoint.name;}
    private boolean flag(String key){return endpoint.settings.path(key).asBoolean();}
    public ObjectNode request(List<ObjectNode> messages,ObjectNode options,boolean stream){ObjectNode body=JSON.createObjectNode();body.put("model",endpoint.wireModel);ArrayNode wire=JSON.createArrayNode();for(ObjectNode message:messages)wire.add(message(message));body.set("messages",wire);if(stream){body.put("stream",true);if(flag("supports_usage_in_streaming"))body.set("stream_options",JSON.createObjectNode().put("include_usage",true));}if(flag("supports_store"))body.put("store",false);
        if(options!=null){if(flag("supports_temperature")){if(endpoint.settings.hasNonNull("fixed_temperature"))body.set("temperature",endpoint.settings.get("fixed_temperature"));else{for(String key:List.of("temperature","top_p","frequency_penalty","presence_penalty"))if(options.path(key).asDouble()>0)body.set(key,options.get(key));if(options.path("seed").asLong()>0&&flag("supports_seed"))body.set("seed",options.get("seed"));}}
            int budget=options.path("max_completion_tokens").asInt();if(budget<=0)budget=options.path("max_tokens").asInt();if(budget>0)body.put(defaultString(endpoint.settings.path("max_tokens_field").asText(),"max_completion_tokens"),budget);tools(body,options);
            if(options.has("format")&&flag("supports_response_format")){body.set("response_format",JSON.createObjectNode().put("type","json_object"));if(!wire.isEmpty()){ObjectNode last=(ObjectNode)wire.get(wire.size()-1);if(last.path("content").isTextual())last.put("content",last.path("content").asText()+"\nUse this JSON schema: "+options.get("format"));}}
            if(flag("prompt_cache_key")&&!options.path("cache_retention").asText().equals("none")){String key=clamp(options.path("prompt_cache_key").asText());if(!key.isEmpty()){body.put("prompt_cache_key",key);if(options.path("cache_retention").asText().equals("long"))body.put("prompt_cache_retention","24h");}}
        }
        thinking(body,options,stream);endpoint.settings.path("extra_body").fields().forEachRemaining(e->{if(!body.has(e.getKey()))body.set(e.getKey(),e.getValue());});if(body.has("max_tokens")&&body.has("max_completion_tokens"))body.remove(endpoint.settings.path("max_tokens_field").asText().equals("max_tokens")?"max_completion_tokens":"max_tokens");
        if(endpoint.settings.path("cache_control_format").asText().equals("anthropic")&&(options==null||!options.path("cache_retention").asText().equals("none"))){ObjectNode marker=JSON.createObjectNode().put("type","ephemeral");if(options!=null&&options.path("cache_retention").asText().equals("long"))marker.put("ttl","1h");for(JsonNode m:wire)if(Set.of("system","developer").contains(m.path("role").asText())){cache((ObjectNode)m,marker);break;}for(int i=wire.size()-1;i>=0;i--)if(Set.of("user","assistant","tool").contains(wire.get(i).path("role").asText())&&cache((ObjectNode)wire.get(i),marker))break;JsonNode tools=body.get("tools");if(tools!=null&&!tools.isEmpty())((ObjectNode)tools.get(tools.size()-1)).set("cache_control",marker.deepCopy());}return body;
    }
    private ObjectNode message(ObjectNode message){ObjectNode out=JSON.createObjectNode();String role=message.path("role").asText();out.put("role",role.equals("system")&&endpoint.reasoning&&flag("supports_developer_role")?"developer":role);String content=neutralize(message.path("content").asText());ArrayNode parts=JSON.createArrayNode();
        if(!message.path("multi_content").isEmpty()){for(JsonNode part:message.path("multi_content")){String type=part.path("type").asText();if(type.equals("text")){ObjectNode text=JSON.createObjectNode().put("type","text");String value=neutralize(part.path("text").asText());if(!value.isEmpty())text.put("text",value);parts.add(text);}else if(type.equals("image_url")&&part.hasNonNull("image_url")){parts.add(JSON.createObjectNode().put("type","image_url").set("image_url",image(part.get("image_url"))));}}setParts(out,parts);}
        else if(role.equals("user")&&!message.path("images").isEmpty()){for(JsonNode image:message.path("images"))parts.add(JSON.createObjectNode().put("type","image_url").set("image_url",image(JSON.createObjectNode().put("url",image.asText()).put("detail","auto"))));ObjectNode text=JSON.createObjectNode().put("type","text");if(!content.isEmpty())text.put("text",content);parts.add(text);setParts(out,parts);}
        else if(!content.isEmpty()||message.path("tool_calls").isEmpty())out.put("content",content);
        if(!message.path("tool_calls").isEmpty()){ArrayNode calls=JSON.createArrayNode();for(JsonNode call:message.path("tool_calls")){ObjectNode wire=JSON.createObjectNode();if(!call.path("id").asText().isEmpty())wire.set("id",call.get("id"));wire.put("type",defaultString(call.path("type").asText(),"function"));wire.set("function",JSON.createObjectNode().put("name",call.path("function").path("name").asText()).put("arguments",neutralize(call.path("function").path("arguments").asText())));for(JsonNode field:endpoint.settings.path("tool_call_extra_fields"))if(call.path("provider_metadata").has(field.asText()))wire.set(field.asText(),call.path("provider_metadata").get(field.asText()).deepCopy());calls.add(wire);}out.set("tool_calls",calls);}
        if(role.equals("tool"))for(String key:List.of("tool_call_id","name"))if(!message.path(key).asText().isEmpty())out.set(key,message.get(key));
        if(role.equals("assistant")){if(flag("replay_reasoning_content")&&!message.path("reasoning_content").asText().isEmpty())out.put("reasoning_content",neutralize(message.path("reasoning_content").asText()));if(endpoint.settings.path("thinking_format").asText().equals("openrouter")&&message.path("reasoning_metadata").has("reasoning_details"))out.set("reasoning_details",message.path("reasoning_metadata").get("reasoning_details").deepCopy());}return out;
    }
    private ObjectNode image(JsonNode image){String url=image.path("url").asText();if(!url.startsWith("http://")&&!url.startsWith("https://")&&!url.startsWith("data:"))throw new ModelClientException("Native chat requires an absolute HTTP or data image URL; storage image resolution is not migrated");ObjectNode out=JSON.createObjectNode().put("url",url);if(!image.path("detail").asText().isEmpty())out.set("detail",image.get("detail"));return out;}
    private void setParts(ObjectNode message,ArrayNode parts){if(flag("supports_multi_content"))message.set("content",parts);else{List<String> texts=new ArrayList<>();for(JsonNode part:parts)if(part.path("type").asText().equals("text")&&!part.path("text").asText().isEmpty())texts.add(part.path("text").asText());message.put("content",String.join("\n",texts));}}
    private void tools(ObjectNode body,ObjectNode opts){if(opts.path("tools").isEmpty())return;ArrayNode tools=JSON.createArrayNode();for(JsonNode tool:opts.path("tools")){ObjectNode function=JSON.createObjectNode().put("name",tool.path("function").path("name").asText()).put("description",tool.path("function").path("description").asText());if(tool.path("function").hasNonNull("parameters"))function.set("parameters",tool.path("function").get("parameters").deepCopy());tools.add(JSON.createObjectNode().put("type",defaultString(tool.path("type").asText(),"function")).set("function",function));}body.set("tools",tools);if(opts.hasNonNull("parallel_tool_calls")&&flag("supports_parallel_tool_calls"))body.set("parallel_tool_calls",opts.get("parallel_tool_calls"));String choice=opts.path("tool_choice").asText(),mode=Set.of("none","required","auto").contains(choice)?choice:"function";if(choice.isEmpty()||!contains(endpoint.settings.path("tool_choice_modes"),mode))return;if(mode.equals("function"))body.set("tool_choice",JSON.createObjectNode().put("type","function").set("function",JSON.createObjectNode().put("name",choice)));else body.put("tool_choice",choice);}
    private void thinking(ObjectNode body,ObjectNode opts,boolean stream){String format=endpoint.settings.path("thinking_format").asText();if(format.isEmpty()||format.equals("none"))return;String level=opts==null?"":reasoning(opts);if(level.isEmpty()){if(!flag("thinking_always_send"))return;level="off";}if(LADDER.contains(level)&&!supported(level)){int index=LADDER.indexOf(level);String clamped="auto";for(int i=index+1;i<LADDER.size();i++)if(supported(LADDER.get(i))){clamped=LADDER.get(i);break;}if(clamped.equals("auto"))for(int i=index-1;i>=0;i--)if(supported(LADDER.get(i))){clamped=LADDER.get(i);break;}level=clamped;}
        boolean enabled=!level.equals("off");if(enabled&&!stream&&flag("thinking_disable_on_non_stream"))enabled=false;if(!enabled&&!supported("off"))return;String effort=enabled&&LADDER.contains(level)&&flag("supports_reasoning_effort")?(endpoint.thinking.hasNonNull(level)?endpoint.thinking.path(level).asText():level):"",field=defaultString(endpoint.settings.path("reasoning_effort_field").asText(),"reasoning_effort");int budget=enabled&&opts!=null&&!endpoint.settings.path("thinking_budget_field").asText().isEmpty()?opts.path("thinking_budget_tokens").asInt():0;if(!effort.isEmpty()&&flag("thinking_budget_excludes_effort"))budget=0;if(budget>0)body.put(endpoint.settings.path("thinking_budget_field").asText(),budget);
        switch(format){case "openai":if(enabled){if(!effort.isEmpty())body.put(field,effort);}else if(endpoint.thinking.hasNonNull("off")&&!endpoint.thinking.path("off").asText().isEmpty())body.put(field,endpoint.thinking.path("off").asText());break;case "thinking-type":body.set("thinking",JSON.createObjectNode().put("type",enabled?defaultString(endpoint.settings.path("thinking_enabled_value").asText(),"enabled"):"disabled"));if(enabled&&!effort.isEmpty())body.put(field,effort);break;case "enable-thinking":body.put("enable_thinking",enabled);if(!effort.isEmpty())body.put(field,effort);break;case "chat-template-kwargs":body.set("chat_template_kwargs",JSON.createObjectNode().put("enable_thinking",enabled));if(!effort.isEmpty())body.put(field,effort);break;case "openrouter":ObjectNode reasoning=JSON.createObjectNode();if(enabled&&!effort.isEmpty())reasoning.put("effort",effort);else reasoning.put("enabled",enabled);body.set("reasoning",reasoning);break;}
    }
    private boolean supported(String level){if(endpoint.thinking.has(level))return !endpoint.thinking.get(level).isNull();return !Set.of("xhigh","max").contains(level);}
    private static String reasoning(ObjectNode opts){String level=opts.path("reasoning_effort").asText();if(Set.of("none","false","disabled").contains(level))return "off";if(Set.of("true","enabled","default","on").contains(level))return "auto";if(Set.of("off","auto","minimal","low","medium","high","xhigh","max").contains(level))return level;if(opts.hasNonNull("thinking"))return opts.path("thinking").asBoolean()?"auto":"off";return "";}
    private static String neutralize(String text){String[][]tokens={{"<|","<\u200b|"},{"<｜","<\u200b｜"},{"<start_of_turn>","<\u200bstart_of_turn>"},{"<end_of_turn>","<\u200bend_of_turn>"},{"[INST]","[\u200bINST]"},{"[/INST]","[\u200b/INST]"},{"<<SYS>>","<\u200b<SYS>>"},{"<</SYS>>","<\u200b</SYS>>"}};for(String[] token:tokens)text=text.replace(token[0],token[1]);return text;}
    private static String defaultString(String value,String fallback){return value.isEmpty()?fallback:value;}
    private static boolean contains(JsonNode values,String needle){for(JsonNode value:values)if(value.asText().equals(needle))return true;return false;}
    private static String clamp(String key){int runes=key.codePointCount(0,key.length());return runes<=64?key:key.substring(0,key.offsetByCodePoints(0,64));}
    private static boolean cache(ObjectNode message,ObjectNode marker){JsonNode content=message.get("content");if(content==null||content.isNull())return false;if(content.isTextual()){if(content.asText().isEmpty())return false;message.set("content",JSON.createArrayNode().add(JSON.createObjectNode().put("type","text").put("text",content.asText()).set("cache_control",marker.deepCopy())));return true;}if(content.isArray())for(int i=content.size()-1;i>=0;i--)if(Set.of("text","tool_result").contains(content.get(i).path("type").asText())){((ObjectNode)content.get(i)).set("cache_control",marker.deepCopy());return true;}return false;}
    private Map<String,String> headers(ObjectNode opts,boolean stream){Map<String,String> headers=new TreeMap<>(String.CASE_INSENSITIVE_ORDER);headers.putAll(endpoint.headers(stream));if(flag("prompt_cache_key")&&opts!=null){String key=clamp(opts.path("prompt_cache_key").asText());if(!key.isEmpty())for(String name:List.of("session_id","x-client-request-id","x-session-affinity"))headers.put(name,key);}return headers;}
    private Duration timeout(CallContext context,boolean stream){return context.deadline()==null?(stream?streamTimeout:chatTimeout):Duration.ZERO;}
    private SafeModelHttp.Response sendOnce(CallContext context,List<ObjectNode> messages,ObjectNode opts,boolean stream){SafeModelHttp.Response response=http.post(context,endpoint.url,headers(opts,stream),request(messages,opts,stream).toString().getBytes(StandardCharsets.UTF_8),timeout(context,stream));if(response.status()<200||response.status()>=300){try(response){throw new ModelHttpException(response.status(),response.text(1<<20),endpoint);}}return response;}
    private SafeModelHttp.Response send(CallContext context,List<ObjectNode> messages,ObjectNode opts,boolean stream){ObjectNode effective=ChatInputs.options(context,opts);try{return sendOnce(context,messages,effective,stream);}catch(ModelHttpException ex){if(!ex.retryWithoutImages())throw ex;return sendOnce(context,ChatInputs.stripImages(messages),effective,stream);}}
    @Override public ObjectNode chat(CallContext context,List<ObjectNode> messages,ObjectNode opts){try(var response=send(context,messages,opts,false)){return decode(JSON.readTree(response.bytes(64<<20)));}catch(IOException ex){throw new ModelClientException("decode response: invalid JSON");}}
    public ObjectNode decode(JsonNode response){if(response==null||!response.isObject())throw new ModelClientException("decode response: expected JSON object");if(!response.path("error").path("message").asText().isEmpty())throw new ModelClientException(endpoint.safe("API error: "+response.path("error").path("message").asText()));JsonNode choices=response.path("choices");if(!choices.isArray()||choices.isEmpty())throw new ModelClientException("no response from API");JsonNode choice=choices.get(0),message=choice.path("message");String content=text(message,"content"),reasoning=reasoningText(message),trimmed=content.strip();if(trimmed.startsWith("<think>")){int end=trimmed.lastIndexOf("</think>");String inline=end<0?trimmed.substring(7).strip():trimmed.substring(7,end).strip();content=end<0?"":trimmed.substring(end+8).strip();if(reasoning.isEmpty())reasoning=inline;}
        ObjectNode result=JSON.createObjectNode().put("content",content);if(!reasoning.isEmpty())result.put("reasoning_content",reasoning);if(message.has("reasoning_details"))result.set("reasoning_metadata",JSON.createObjectNode().set("reasoning_details",message.get("reasoning_details").deepCopy()));ArrayNode calls=calls(message.path("tool_calls"));if(!calls.isEmpty())result.set("tool_calls",calls);if(!text(choice,"finish_reason").isEmpty())result.put("finish_reason",text(choice,"finish_reason"));result.set("usage",usage(response.path("usage"),flag("prompt_cache_accounting")));return result;
    }
    private String reasoningText(JsonNode message){for(JsonNode field:endpoint.settings.path("reasoning_fields")){String key=field.asText();if(Set.of("reasoning_content","reasoning","reasoning_text").contains(key)&&!text(message,key).isEmpty())return text(message,key);}return "";}
    private static String text(JsonNode node,String key){JsonNode value=node.get(key);if(value==null||value.isNull())return "";if(!value.isTextual())throw new ModelClientException("decode response: "+key+" must be a string");return value.asText();}
    private ArrayNode calls(JsonNode input){ArrayNode out=JSON.createArrayNode();if(input.isMissingNode()||input.isNull())return out;if(!input.isArray())throw new ModelClientException("decode response: tool_calls must be an array");for(JsonNode call:input){if(!call.isObject())throw new ModelClientException("decode tool call: expected object");ObjectNode item=JSON.createObjectNode().put("id",text(call,"id")).put("type",defaultString(text(call,"type"),"function"));item.set("function",JSON.createObjectNode().put("name",text(call.path("function"),"name")).put("arguments",text(call.path("function"),"arguments")));ObjectNode metadata=JSON.createObjectNode();for(JsonNode key:endpoint.settings.path("tool_call_extra_fields"))if(call.hasNonNull(key.asText()))metadata.set(key.asText(),call.get(key.asText()).deepCopy());if(!metadata.isEmpty())item.set("provider_metadata",metadata);out.add(item);}return out;}
    @Override public void stream(CallContext context,List<ObjectNode> messages,ObjectNode opts,Consumer<ObjectNode> consumer){try(var response=send(context,messages,opts,true)){StreamState state=new StreamState(context,consumer);try{while(true){context.check();String line=line(response.body());if(line==null){state.end(true);return;}if(!line.startsWith("data:"))continue;String payload=line.substring(5);if(payload.startsWith(" "))payload=payload.substring(1);if(payload.strip().equals("[DONE]")){state.end(false);return;}if(payload.isEmpty())continue;JsonNode envelope;try{envelope=JSON.readTree(payload);}catch(IOException ex){throw new ModelClientException("decode stream chunk: invalid JSON");}if(envelope==null||!envelope.isObject())throw new ModelClientException("decode stream chunk: expected object");if(!envelope.path("error").path("message").asText().isEmpty())throw new ModelClientException(endpoint.safe("API stream error: "+envelope.path("error").path("message").asText()));if(envelope.hasNonNull("usage"))state.usage=usage(envelope.get("usage"),flag("prompt_cache_accounting"));JsonNode choices=envelope.path("choices");if(choices.isMissingNode()||choices.isNull())continue;if(!choices.isArray())throw new ModelClientException("decode stream chunk: choices must be an array");if(!choices.isEmpty())state.process(choices.get(0));}}catch(CancellationException ex){throw ex;}catch(ModelClientException|IOException ex){context.check();state.fail(ex.getMessage());}}}
    private static String line(InputStream input)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();while(true){int c=input.read();if(c<0){if(bytes.size()==0)return null;break;}if(c=='\n')break;if(bytes.size()>=1<<20)throw new ModelClientException("Stream line exceeds Go SSE maximum size");bytes.write(c);}byte[] raw=bytes.toByteArray();int length=raw.length;if(length>0&&raw[length-1]=='\r')length--;return new String(raw,0,length,StandardCharsets.UTF_8);}
    private final class StreamState {
        private final ModelStreamAssembler assembler;private final ArrayNode reasoningDetails=JSON.createArrayNode();private ObjectNode usage;
        StreamState(CallContext context,Consumer<ObjectNode> consumer){assembler=new ModelStreamAssembler(context,consumer,endpoint);}
        private void process(JsonNode choice){JsonNode delta=choice.path("delta"),raw=delta.path("tool_calls");ArrayNode decoded=calls(raw);List<ModelStreamAssembler.ToolDelta> fragments=new ArrayList<>();Map<Integer,ObjectNode> metadata=new LinkedHashMap<>();
            for(int i=0;i<decoded.size();i++){JsonNode original=raw.get(i);if(original.hasNonNull("index")&&(!original.get("index").isIntegralNumber()||!original.get("index").canConvertToInt()))throw new ModelClientException("decode tool call: index must be an integer");int index=original.hasNonNull("index")?original.path("index").asInt():i;ObjectNode part=(ObjectNode)decoded.get(i);fragments.add(new ModelStreamAssembler.ToolDelta(index,text(part,"id"),text(part,"type"),text(part.path("function"),"name"),text(part.path("function"),"arguments")));if(part.has("provider_metadata"))metadata.put(index,(ObjectNode)part.get("provider_metadata"));}
            if(delta.path("reasoning_details").isArray())delta.path("reasoning_details").forEach(d->reasoningDetails.add(d.deepCopy()));assembler.process(reasoningText(delta),text(delta,"content"),fragments,text(choice,"finish_reason"));metadata.forEach(assembler::metadata);
        }
        private void prepare(){if(usage!=null)assembler.usage(usage);if(!reasoningDetails.isEmpty())assembler.reasoning(JSON.createObjectNode().set("reasoning_details",reasoningDetails));}
        private void end(boolean eof){prepare();if(eof)assembler.endAtEOF();else assembler.end();}
        private void fail(String message){prepare();assembler.fail(message);}
    }
    public static ObjectNode usage(JsonNode source,boolean accounting){ObjectNode out=JSON.createObjectNode();int prompt=source.path("prompt_tokens").asInt(),completion=source.path("completion_tokens").asInt(),total=source.path("total_tokens").asInt();out.put("prompt_tokens",prompt);out.put("completion_tokens",completion);out.put("total_tokens",total==0?prompt+completion:total);int read=0,write=0,miss=0;boolean reported=true;
        if(source.hasNonNull("prompt_cache_hit_tokens")||source.hasNonNull("prompt_cache_miss_tokens")){read=source.path("prompt_cache_hit_tokens").asInt();miss=source.path("prompt_cache_miss_tokens").asInt();}else if(source.hasNonNull("cache_read_input_tokens")||source.hasNonNull("cache_creation_input_tokens")){read=source.path("cache_read_input_tokens").asInt();write=source.path("cache_creation_input_tokens").asInt();miss=Math.max(0,prompt-read);}else if(source.path("prompt_tokens_details").hasNonNull("cached_tokens")||source.path("prompt_tokens_details").hasNonNull("cache_write_tokens")){read=source.path("prompt_tokens_details").path("cached_tokens").asInt();write=source.path("prompt_tokens_details").path("cache_write_tokens").asInt();miss=Math.max(0,prompt-read);}else if(source.hasNonNull("cached_tokens")){read=source.path("cached_tokens").asInt();miss=Math.max(0,prompt-read);}else reported=false;read=Math.max(0,read);write=Math.max(0,write);miss=Math.max(0,miss);if(read>0){out.put("cached_tokens",read);out.put("cache_read_tokens",read);}if(write>0)out.put("cache_write_tokens",write);if(miss>0)out.put("cache_miss_tokens",miss);out.put("cache_reported",reported);out.put("cache_status",reported?(read>0?"hit":"miss"):(accounting?"unreported":"unsupported"));return out;
    }
}
